import { useState } from 'react';
import { toast } from 'sonner';
import TrashIcon from '@/components/icons/TrashIcon';
import { ColumnDef, Row } from '@tanstack/react-table';
import { Link, useNavigate } from 'react-router-dom';
import { cn } from '@/lib/utils';
import ArrowBackIcon from '@/components/icons/ArrowBackIcon';
import { Booking } from '@/features/booking/types/Booking.types';
import ViewIcon from '@/components/icons/ViewIcon';
import DeletePopup from '@/components/Popups/DeletePopup';
import { endpoints } from '@/lib/axios/axios-global';

// Create a separate component for the actions cell
const ActionsCell = ({ row }: { row: Row<Booking> }) => {
    const navigate = useNavigate();
    const [showDeletePopup, setShowDeletePopup] = useState(false);

    const handleDeleteClick = () => setShowDeletePopup(true);
    const handleCancel = () => setShowDeletePopup(false);
    const handleSuccess = () => {
        toast.success('تم حذف التعاقد بنجاح');
        setShowDeletePopup(false);
        (row.original as Booking & { refreshTable?: () => void }).refreshTable?.();
    };

    return (
        <>
            <div className="me-6 text-end flex flex-row items-center justify-end gap-6">
                <button className="hover:bg-white-blue-300 rounded-full p-1">
                    <ArrowBackIcon className="text-primery-blue-400 cursor-pointer" width="20" height="20" />
                </button>

                <Link
                    to={`/customer-relations/view-customer/${row.original.customer.id}`}
                    className="hover:bg-white-blue-300 rounded-full p-1"
                >
                    <ViewIcon className="text-primery-blue-400 cursor-pointer" width="20" height="20" />
                </Link>

                <button type="button" onClick={handleDeleteClick} className="hover:bg-white-blue-300 rounded-full p-1">
                    <TrashIcon className="text-[#E81E1E] cursor-pointer" />
                </button>

            </div>
            {showDeletePopup && (
                <DeletePopup
                    open={showDeletePopup}
                    text="هل أنت متأكد أنك تريد حذف هذا التعاقد؟"
                    endpoint={endpoints.contract.delete + row.original.id}
                    handleCancel={handleCancel}
                    handleSuccess={handleSuccess}
                />
            )}
        </>
    );
};

export const columns: ColumnDef<Booking>[] = [
    {
        accessorKey: 'rent',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    العميل / الجهة
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                {row.original.customer.full_name}
            </div>
        ),
    },
    {
        accessorKey: 'phone',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    تاريخ بداية التعاقد
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-[#625E74] leading-[26.24px] font-semibold tracking-normal">
                {row.original.start_date}
            </div>
        ),
    },
    {
        accessorKey: 'phone',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    تاريخ نهاية التعاقد
                </div>
            );
        },
        cell: ({ row }) => (
            <div className="text-sm px-4 py-3 !text-[#625E74] leading-[26.24px] font-semibold tracking-normal">
                {row.original.end_date}
            </div>
        ),
    },
    {
        accessorKey: 'service',
        header: () => {
            return (
                <div className="text-sm px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    حالة التعاقد
                </div>
            );
        },
        cell: ({ row }) => {
            return (
                <div className="text-xs font-medium tracking-normal leading-[115%]">
                    <p
                        className={cn('p-1 w-fit rounded-sm', {
                            'bg-[#DAF8E6] text-[#1A8245]': row.original.status === 'completed',
                            'bg-[#FFFBEB] text-[#D97706]': row.original.status === 'pending',
                            'bg-[#FEEBEB] text-[#E10E0E]': row.original.status === 'rejected',
                        })}
                    >
                        {row.original.status}
                    </p>
                </div>
            );
        },
    },
    {
        id: 'actions',
        header: () => {
            return (
                <div className="text-sm text-center px-4 py-3 !text-primery-blue-500 leading-[26.24px] font-semibold tracking-normal">
                    تصدير
                </div>
            );
        },
        cell: ({ row }) => <ActionsCell row={row} />,
    },
];
